import { cookies, headers } from 'next/headers'

const DEFAULT_THEME = 'light'
const DEFAULT_LANGUAGE = 'en'

/**
 * Picks the highest-priority language tag out of an Accept-Language header, e.g.
 * `fr-CH, fr;q=0.9, en;q=0.8, *;q=0.5` -> `fr-CH`.
 */
function parsePreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return DEFAULT_LANGUAGE

  const candidates = acceptLanguage
    .split(',')
    .map((entry) => {
      const [tag, ...params] = entry.split(';').map((part) => part.trim())
      const quality = params.find((param) => param.startsWith('q='))
      const q = quality ? Number.parseFloat(quality.slice(2)) : 1
      return { tag, q: Number.isNaN(q) ? 0 : q }
    })
    // `*` matches any language rather than naming one, and `q=0` means "not acceptable".
    .filter(({ tag, q }) => tag !== '' && tag !== '*' && q > 0)

  if (candidates.length === 0) return DEFAULT_LANGUAGE

  // reduce() keeps the first entry on equal q-values, which is the precedence the
  // header order is meant to convey (RFC 9110 §12.5.4).
  return candidates.reduce((best, entry) => (entry.q > best.q ? entry : best)).tag
}

export default async function UserPreferences() {
  // In Next.js 15+ both of these are async and must be awaited.
  const [cookieStore, headerList] = await Promise.all([cookies(), headers()])

  const theme = cookieStore.get('theme')?.value || DEFAULT_THEME
  const language = parsePreferredLanguage(headerList.get('accept-language'))

  return (
    <section>
      <h2>Preferences</h2>
      <dl>
        <dt>Theme</dt>
        <dd>{theme}</dd>
        <dt>Preferred language</dt>
        <dd>{language}</dd>
      </dl>
    </section>
  )
}

